function env(name, fallback = '') {
  try { return $env[name] || fallback; } catch (error) { return fallback; }
}
const query = $json.query || {};
const expected = env('INSTAGRAM_VERIFY_TOKEN_JIW');
const mode = query['hub.mode'] || query.hub_mode;
const token = query['hub.verify_token'] || query.hub_verify_token;
const challenge = query['hub.challenge'] || query.hub_challenge || '';
if (expected && token !== expected) {
  return { json: { ok: false, statusCode: 403, challenge: 'invalid_verify_token' } };
}
return { json: { ok: true, statusCode: mode === 'subscribe' ? 200 : 400, challenge } };

async function main(helpers) {
  const input = typeof $json.body === 'string' ? JSON.parse($json.body || '{}') : ($json.body || $json);

  function env(name, fallback = '') {
    try { return $env[name] || fallback; } catch (error) { return fallback; }
  }

  function firstMessaging(body) {
    const entries = body.entry || [];
    for (const entry of entries) {
      for (const messaging of entry.messaging || []) {
        if (messaging?.message?.is_echo) continue;
        if (messaging?.sender?.id) return { entry, messaging };
      }
    }
    return { entry: null, messaging: null };
  }

  function normalizeText(message) {
    const text = String(message?.text || '').trim();
    const attachments = message?.attachments || [];
    if (text) return { text, contentType: 'text', unsupported: false };
    const type = attachments[0]?.type || 'unsupported';
    if (type === 'image') return { text: '[Imagem recebida pelo Instagram]', contentType: 'image', unsupported: true };
    if (type === 'audio') return { text: '[Audio recebido pelo Instagram]', contentType: 'audio', unsupported: true };
    if (type === 'video') return { text: '[Video recebido pelo Instagram]', contentType: 'video', unsupported: true };
    return { text: '[Mensagem sem texto recebida pelo Instagram]', contentType: 'unknown', unsupported: true };
  }

  function classify(rawText) {
    const normalized = rawText.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const hasAny = (words) => words.some((word) => normalized.includes(word));
    let service = 'geral';
    let stage = 'Qualificacao';
    let handoff = false;
    let response = '';

    if (hasAny(['sistema','software','app','aplicativo','site','landing page','automacao','integracao','api','crm','dashboard'])) service = 'software_house';
    else if (hasAny(['suporte','erro','computador','notebook','internet','rede','servidor','email','impressora','ti','manutencao'])) service = 'suporte_ti';
    else if (hasAny(['trafego','anuncio','google ads','meta ads','facebook ads','campanha','leads','vendas online'])) service = 'trafego_pago';
    else if (hasAny(['social media','instagram','conteudo','post','reels','criativo','identidade visual'])) service = 'social_media';
    else if (hasAny(['consultoria','digital','processo','tecnologia para empresa'])) service = 'consultoria_digital';

    if (!rawText || rawText.startsWith('[')) {
      response = 'Recebi sua mensagem. No momento consigo atender melhor por texto. Me envie o que sua empresa precisa: software, suporte de TI, trafego pago, social media, site, automacao ou consultoria digital.';
    } else if (hasAny(['orcamento','quanto custa','preco','valor','proposta','contrato'])) {
      stage = 'Orcamento solicitado';
      handoff = true;
      response = 'Perfeito. Para preparar um orcamento, me envie nome da empresa, servico desejado, objetivo principal, prazo desejado e melhor contato. Vou sinalizar um especialista da JIW. [HUMANO_SOLICITADO]';
    } else if (service === 'software_house') {
      stage = 'Briefing necessario';
      response = 'Entendi. A JIW pode ajudar com sistemas, apps, sites, landing pages, dashboards, integracoes e automacoes. O que voce quer construir ou automatizar?';
    } else if (service === 'suporte_ti') {
      stage = 'Suporte tecnico';
      handoff = hasAny(['urgente','fora do ar','parado','caiu','sem internet','nao funciona']);
      response = 'Certo. Para suporte de TI, me envie qual equipamento, sistema ou servico esta com problema, quantas pessoas foram impactadas e se e urgente.' + (handoff ? ' [HUMANO_SOLICITADO]' : '');
    } else if (service === 'trafego_pago') {
      stage = 'Briefing necessario';
      response = 'A JIW pode ajudar com trafego pago para leads, vendas e posicionamento. Qual produto ou servico voce vende e qual objetivo principal da campanha?';
    } else if (service === 'social_media') {
      stage = 'Briefing necessario';
      response = 'A JIW pode apoiar sua empresa com social media, conteudo, criativos e presenca digital. Qual e o segmento da empresa e quais redes usa hoje?';
    } else if (hasAny(['oi','ola','bom dia','boa tarde','boa noite','teste'])) {
      response = 'Ola! Sou o assistente da JIW - Solucoes tecnologicas. A JIW ajuda empresas com sistemas, sites, automacoes, suporte de TI, trafego pago, social media e consultoria digital. Me diga em poucas palavras o que voce precisa.';
    } else if (hasAny(['humano','atendente','especialista','reuniao','ligar','whatsapp'])) {
      stage = 'Atendimento humano';
      handoff = true;
      response = 'Claro. Vou encaminhar seu atendimento para um especialista da JIW continuar com voce. [HUMANO_SOLICITADO]';
    } else if (hasAny(['receita','bolo','piada','musica','filme','jogo'])) {
      stage = 'Fora de contexto';
      response = 'Nao consegui relacionar sua mensagem aos servicos da JIW. Posso ajudar com software, suporte de TI, trafego pago, social media, sites, automacoes ou consultoria digital. Pode reformular nesse contexto?';
    } else {
      response = 'Entendi. Sua necessidade esta mais ligada a software/site/automacao, suporte de TI, trafego pago, social media ou consultoria digital?';
    }
    return { service, stage, handoff, response };
  }

  async function insertEvent(event) {
    const supabaseUrl = env('SUPABASE_URL').replace(/\/$/, '');
    const serviceKey = env('SUPABASE_SERVICE_ROLE_KEY');
    if (!supabaseUrl || !serviceKey) throw new Error('Supabase nao configurado no n8n');
    return await helpers.httpRequest({
      method: 'POST',
      url: supabaseUrl + '/rest/v1/channel_events',
      headers: {
        'Content-Type': 'application/json',
        apikey: serviceKey,
        Authorization: 'Bearer ' + serviceKey,
        Prefer: 'return=representation',
      },
      body: event,
      json: true,
    });
  }

  async function sendInstagram(recipientId, text) {
    const token = env('INSTAGRAM_PAGE_ACCESS_TOKEN_JIW');
    if (!token) return { ok: false, skipped: true, reason: 'INSTAGRAM_PAGE_ACCESS_TOKEN_JIW nao configurado' };
    return await helpers.httpRequest({
      method: 'POST',
      url: 'https://graph.facebook.com/v18.0/me/messages',
      qs: { access_token: token },
      headers: { 'Content-Type': 'application/json' },
      body: { recipient: { id: recipientId }, message: { text } },
      json: true,
    });
  }

  if (input.object && input.object !== 'instagram') return { ok: true, ignored: true, reason: 'object_not_instagram' };
  const { entry, messaging } = firstMessaging(input);
  if (!messaging) return { ok: true, ignored: true, reason: 'no_messaging_event' };

  const senderId = String(messaging.sender.id);
  const message = messaging.message || {};
  const normalized = normalizeText(message);
  const classification = classify(normalized.text);
  const responseText = classification.response.replace(/\[HUMANO_SOLICITADO\]/g, '').trim();
  const instagram = await sendInstagram(senderId, responseText);

  const event = {
    tenant_slug: 'jiw',
    channel_type: 'instagram',
    external_conversation_id: senderId,
    external_message_id: message.mid || 'instagram:' + senderId + ':' + Date.now(),
    direction: 'inbound',
    sender_type: 'contact',
    contact_name: 'Contato Instagram',
    contact_handle: senderId,
    message_text: normalized.text,
    service: classification.service,
    stage: classification.stage,
    handoff: classification.handoff,
    response_text: classification.response,
    ai_provider: 'fallback_rules',
    ai_model: 'instagram-rules-v1',
    ai_usage: {},
    catalog_matches: [],
    raw_payload: { entry, messaging, instagram, content_type: normalized.contentType, unsupported: normalized.unsupported },
  };
  const saved = await insertEvent(event);
  return { ok: true, tenant_slug: 'jiw', channel_type: 'instagram', external_conversation_id: senderId, message_text: normalized.text, response_sent: Boolean(instagram?.ok), instagram, saved };
}

try {
  return { json: await main(this.helpers) };
} catch (error) {
  return { json: { ok: false, error: error.message || String(error) } };
}
